297	export async function open(browser, baseUrl) {
298	  const page = await browser.newPage();
299	  await page.enable();
300	  await page.addInitScript(INIT_SOURCE);
301	  await page.goto(baseUrl);
302	  // Initial list fetch has settled.
303	  await waitListSettled(page);
304	  return page;
305	}
