458	    var box = document.getElementById('conflict-box');
459	    function column(selector) {
460	      var ver = box.querySelector(selector);
461	      if (!ver) return null;
462	      var dds = ver.querySelectorAll('dd');
463	      function val(dd) { return dd.classList.contains('empty-field') ? '' : dd.textContent; }
464	      return {
465	        heading: ver.querySelector('h4').textContent,
466	        title: val(dds[0]),
467	        summary: val(dds[1]),
468	        body: val(dds[2])
469	      };
470	    }
471	    return {
472	      hidden: box.hidden,
473	      heading: box.querySelector('h3') ? box.querySelector('h3').textContent : '',
474	      mine: column('.ver.mine'),
475	      saved: column('.ver.saved'),
476	      actions: Array.prototype.map.call(
477	        box.querySelectorAll('.actions button'),
478	        function (btn) { return { text: btn.textContent, disabled: btn.disabled }; })
479	    };
480	  })()`);
481	}
482	
483	export function assertNoPageErrors(page) {
484	  if (page.pageErrors.length) {
485	    throw new Error(`uncaught page errors:\n${page.pageErrors.join('\n')}`);
486	  }
487	  const errors = page.consoleMessages.filter((m) => m.type === 'error');
488	  if (errors.length) {
489	    throw new Error(`console errors:\n${errors.map((m) => m.text).join('\n')}`);
490	  }
491	  if (page.dialogs.length) {
492	    throw new Error(`unexpected native confirm/alert dialogs (dirty-guard fired?):\n${page.dialogs.join('\n---\n')}`);
493	  }
494	}
