1741	    const current = await seed(server, {
1742	      title: '正在编辑的草稿', summary: '原摘要', body: '原正文',
1743	    });
1744	    const targetA = await seed(server, { title: '目标草稿甲', summary: '目标摘要甲', body: '目标正文甲' });
1745	    await ui.reload(page);
1746	    await ui.clickEdit(page, '正在编辑的草稿');
1747	    await ui.waitLoadedDraft(page);
1748	    const typed = { title: '未保存的新标题', summary: '未保存的新摘要', body: '未保存的新正文' };
1749	    await ui.fill(page, typed);
1750	
1751	    // 取消：不读取目标草稿，表单、编辑对象、版本基准、列表卡片全部不变。
1752	    await ui.setConfirm(page, 'cancel');
1753	    await ui.readGateOn(page);
1754	    await ui.resetConfirm(page);
1755	    await ui.clickEdit(page, '目标草稿甲');
1756	    await sleep(50); // 留出时间证明根本没有发出读取请求
1757	    let confirm = await ui.confirmState(page);
1758	    assert.equal(confirm.calls.length, 1);
1759	    assert.match(confirm.calls[0], /当前表单有未保存的修改/);
1760	    assert.match(confirm.calls[0], /打开另一篇草稿将放弃这些输入/);
1761	    assert.deepEqual(await ui.readGateState(page), { enabled: true, hits: 0, pending: 0 });
1762	    let s = await ui.state(page);
1763	    assert.deepEqual(s.form, typed);
1764	    assert.equal(s.formEditing, true);
1765	    assert.equal(s.bannerId, current.id);
1766	    assert.equal(s.saveBtnText, '保存修改');
1767	    assert.equal(s.saveDisabled, false);
1768	    assert.ok(!s.statusText.includes('正在读取'));
1769	    // 目标卡片不能被标记为编辑中，原草稿仍是唯一“编辑中”卡片。
1770	    assert.equal(s.cards.find((c) => c.title === '正在编辑的草稿').editing, true);
1771	    assert.equal(s.cards.find((c) => c.title === '目标草稿甲').editing, false);
1772	    // 什么都没保存：两篇草稿的已保存内容与版本都不动。
1773	    assert.deepEqual(
1774	      { title: (await getArticle(server, current.id)).title, version: (await getArticle(server, current.id)).version },
1775	      { title: '正在编辑的草稿', version: 1 });
1776	
1777	    // 确认继续：才发出单篇读取并进入读取中状态。
1778	    await ui.setConfirm(page, 'accept');
1779	    await ui.resetConfirm(page);
1780	    await ui.clickEdit(page, '目标草稿甲');
1781	    await ui.waitReadPending(page, 1);
1782	    confirm = await ui.confirmState(page);
1783	    assert.equal(confirm.calls.length, 1, '进入读取只经过一次“是否放弃”确认');
1784	    s = await ui.state(page);
1785	    assert.deepEqual(s.fieldsEditable, { title: true, summary: true, body: true });
1786	    assert.equal(s.saveBtnText, '读取中…');
1787	    assert.equal(s.saveDisabled, true);
1788	    assert.match(s.statusText, /正在读取/);
1789	    // 读取期间不能提前清空表单，也不能提前切换编辑对象/卡片标记。
1790	    assert.deepEqual(s.form, typed);
1791	    assert.equal(s.bannerId, current.id);
1792	    assert.equal(s.cards.find((c) => c.title === '正在编辑的草稿').editing, true);
1793	    assert.equal(s.cards.find((c) => c.title === '目标草稿甲').editing, false);
1794	    await ui.releaseReads(page);
1795	    await ui.readGateOff(page);
1796	    await ui.waitLoadedDraft(page);
1797	    s = await ui.state(page);
1798	    assert.equal(s.bannerId, targetA.id);
1799	    assert.deepEqual(s.form, { title: '目标草稿甲', summary: '目标摘要甲', body: '目标正文甲' });
1800	    assert.equal(s.cards.find((c) => c.title === '目标草稿甲').editing, true);
1801	    // 打开本身不保存：目标仍是版本 1，两篇记录都在。
