    assert.deepEqual(
      { title: (await getArticle(server, article.id)).title, version: (await getArticle(server, article.id)).version },
      { title: v2.title, version: 2 }, '原冲突草稿仍保持对方保存的内容');
  } finally {
    await closeContext(ctx, browser);
  }
});

